-- gap drop:757:2:1, written by an automated writer
test('breakit Drive.Log: pruning keeps the newest hours in the saved log', function()
    local w = T.newWorld()
    local r = T.rider(w, T.TESTCHAR)
    T.settle(w)
    r.env.time = function() return 1700000000 end
    local db = r.W.db
    db.drive = db.drive or {}
    db.drive.log = db.drive.log or {}
    local l = db.drive.log
    l.open = {}
    for i = 0, 99999 do l.open[string.format('9999%06d', i)] = 1 end
    l.seen = {}
    for i = 0, 99999 do l.seen[string.format('8888%06d', i)] = 1 end
    r.W.Drive.LogPrune()
    local function newestBlock(map, first)
        local n, min, max = 0, nil, nil
        for k in pairs(map) do
            local v = tonumber(k)
            n = n + 1
            if not min or v < min then min = v end
            if not max or v > max then max = v end
        end
        if n == 0 then return false end
        return max - min + 1 == n and map[first] == nil
    end
    ok(newestBlock(l.open, '9999000000'), 'open log keeps a consecutive newest block')
    ok(newestBlock(l.seen, '8888000000'), 'seen log keeps a consecutive newest block')
